# Try World Bank API for Georgia GDP data as backup
curl -sL --max-time 20 "https://api.worldbank.org/v2/country/GEO/indicator/NY.GDP.MKTP.KD?format=json&date=2000:2025&per_page=100" 2>/dev/null | python3 -c "
import sys, json
try:
    data = json.load(sys.stdin)
    if data and len(data) > 1:
        for item in data[1][:10]:
            print(f\"{item['date']}: {item['value']}\")
    else:
        print('No data')
except Exception as e:
    print(f'Error: {e}')
"

# Try World Bank API for GDP in current LCU (national currency)
curl -sL --max-time 20 "https://api.worldbank.org/v2/country/GEO/indicator/NY.GDP.MKTP.CN?format=json&date=2000:2025&per_page=100" 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data and len(data) > 1:
    for item in sorted(data[1], key=lambda x: x['date'], reverse=True):
        if item['value']:
            print(f\"{item['date']}: {item['value']}\")
" 2>/dev/null

# Get World Bank real GDP in constant 2015 USD for Georgia
curl -sL --max-time 20 "https://api.worldbank.org/v2/country/GEO/indicator/NY.GDP.MKTP.KD?format=json&date=2000:2025&per_page=100" 2>/dev/null | python3 -c "
import sys, json
data = json.load(sys.stdin)
if data and len(data) > 1:
    for item in sorted(data[1], key=lambda x: x['date']):
        if item['value']:
            print(f\"{item['date']}: {item['value']}\")
"
